import { PiyAPIClient } from '@piyapi/sdk';

// Scoped multi-tenant client instance
const client = new PiyAPIClient({
  apiKey: process.env.PIYAPI_API_KEY,
  headers: {
    'X-Namespace-Prefix': 'tenant_acme_corp_prod'
  }
});

// Store facts scoped strictly to user and session
await client.memories.store({
  content: "User authorized enterprise SSO with Okta provider",
  user_id: "usr_alex_88",
  session_id: "sess_onboarding_992",
  metadata: { org_id: "org_acme_corp" }
});
